        require(msg.sender != to);
        require(value > 0);
        require( balances[msg.sender] >= value );
        require( balances[to] + value >= balances[to] );
        if(msg.sender == team) {
            require(now >= 1589036400);      
            if(balances[msg.sender] - value < toWei(600000000))
                require(now >= 1620572400);      
